"""Tenant-scoped write gate for a delegated agent."""


class Context:
    def __init__(self, tenant_id, agent_id, scopes, active):
        self.tenant_id = tenant_id
        self.agent_id = agent_id
        self.scopes = tuple(scopes)
        self.active = active


class Resource:
    def __init__(self, tenant_id):
        self.tenant_id = tenant_id


def may_write(ctx, resource):
    return REPLACE_ME
